#!/usr/bin/env python3
"""Trains the small reference CNN (conv 3x3 x32 + ReLU + 2x2 max pool, conv 3x3 x64 + ReLU + 2x2 max pool, fully connected 3,136 -> 10; the same architecture as the 'small CNN' of the accuracy comparisons) on Fashion-MNIST, quantises it to int8 (symmetric per-tensor weights, uint8 activations
with scales calibrated on training images, int32 accumulators, fixed-point requantisation: no floating point at inference), checks the quantised model in numpy on the 10,000 test images, and writes cnn_tables.h for the C port (cnn_core.c).
This is a REFERENCE BASELINE for the microcontroller energy measurement, not a part of L. usage: python gen_cnn.py DATA_DIR [epochs=10]"""
import os, sys, time
import numpy as np, torch, torch.nn as nn
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, os.path.join(HERE, "..", "brain"))
from cortex_core import load  # noqa
D = sys.argv[1]; EP = int(sys.argv[2]) if len(sys.argv) > 2 else 10; torch.manual_seed(0); torch.set_num_threads(3); t0 = time.time()
xtr, ytr, xte, yte = load(D, "fashion"); ytr, yte = ytr.astype(np.int64), yte.astype(np.int64)
net = nn.Sequential(nn.Conv2d(1, 32, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2), nn.Conv2d(32, 64, 3, padding=1), nn.ReLU(), nn.MaxPool2d(2), nn.Flatten(), nn.Dropout(0.3), nn.Linear(64 * 49, 10))
X = lambda a: torch.tensor(a.reshape(-1, 1, 28, 28) / 255.0, dtype=torch.float32); A, T = X(xtr), X(xte); y = torch.tensor(ytr); opt = torch.optim.Adam(net.parameters(), 1e-3)
for ep in range(EP):
    net.train(); perm = torch.randperm(len(y))
    for i in range(0, len(y), 128): ix = perm[i:i + 128]; opt.zero_grad(); nn.functional.cross_entropy(net(A[ix]), y[ix]).backward(); opt.step()
net.eval()
with torch.no_grad(): fl = net(T).argmax(1).numpy()
print("float model: test accuracy %.4f [%.0fs]" % ((fl == yte).mean(), time.time() - t0), flush=True)
W1, B1, W2, B2, W3, B3 = [p.detach().numpy().astype(np.float64) for p in net.parameters() if True][0:6]
# ---- quantisation
def qw(w): s = np.abs(w).max() / 127.0; return np.round(w / s).astype(np.int64), s
q1, sw1 = qw(W1); q2, sw2 = qw(W2); q3, sw3 = qw(W3); s_in = 1.0 / 255.0
def conv(x, w, b, pad=1):    # x (C_in, H, W) int64, w (C_out, C_in, 3, 3) int64 -> int64 accumulators (C_out, H, W)
    cin, H, Wd = x.shape; xp = np.pad(x, ((0, 0), (pad, pad), (pad, pad))); out = np.zeros((w.shape[0], H, Wd), np.int64)
    for ky in range(3):
        for kx in range(3): out += np.einsum("oc,chw->ohw", w[:, :, ky, kx], xp[:, ky:ky + H, kx:kx + Wd])
    return out + b[:, None, None]
def pool(x): c, h, w = x.shape; return x.reshape(c, h // 2, 2, w // 2, 2).max(axis=(2, 4))
cal = xtr[:512].astype(np.int64)
b1q = np.round(B1 / (s_in * sw1)).astype(np.int64); a1 = [np.maximum(conv(im.reshape(1, 28, 28), q1, b1q), 0) for im in cal[:128]]; s1 = max(a.max() for a in a1) * s_in * sw1 / 255.0
M1 = int(round(s_in * sw1 / s1 * 65536))
def l1(im):
    acc = conv(im.reshape(1, 28, 28), q1, b1q); acc = np.maximum(acc, 0); return pool(np.clip((acc * M1 + 32768) >> 16, 0, 255))
a1q = [l1(im) for im in cal[:128]]; b2q = np.round(B2 / (s1 * sw2)).astype(np.int64); a2 = [np.maximum(conv(a, q2, b2q), 0) for a in a1q]; s2 = max(a.max() for a in a2) * s1 * sw2 / 255.0; M2 = int(round(s1 * sw2 / s2 * 65536))
b3q = np.round(B3 / (s2 * sw3)).astype(np.int64)
def fwd(im):
    a = l1(im); acc = np.maximum(conv(a, q2, b2q), 0); a = pool(np.clip((acc * M2 + 32768) >> 16, 0, 255)); return q3 @ a.reshape(-1) + b3q
NQ = 10000; pq = np.array([fwd(xte[i].astype(np.int64)).argmax() for i in range(NQ)]); print("quantised int8 model: test accuracy %.4f on %d images (float %.4f on the same); requantisation multipliers %d, %d (x 2^-16) [%.0fs]" % ((pq == yte[:NQ]).mean(), NQ, (fl[:NQ] == yte[:NQ]).mean(), M1, M2, time.time() - t0), flush=True)
def arr(ctype, name, v, per=24): v = np.asarray(v).reshape(-1); return "static const %s %s[%d] = {\n%s\n};\n" % (ctype, name, len(v), ",\n".join(",".join(str(int(a)) for a in v[i:i + per]) for i in range(0, len(v), per)))
with open(os.path.join(HERE, "cnn_tables.h"), "w") as f:
    f.write("/* generated by gen_cnn.py: small reference CNN, int8 weights, test accuracy %.4f (float %.4f) */\n#pragma once\n#include <stdint.h>\n#define CNN_M1 %d\n#define CNN_M2 %d\n" % ((pq == yte[:NQ]).mean(), (fl == yte).mean(), M1, M2))
    f.write(arr("int8_t", "CNN_W1", q1)); f.write(arr("int32_t", "CNN_B1", b1q)); f.write(arr("int8_t", "CNN_W2", q2)); f.write(arr("int32_t", "CNN_B2", b2q)); f.write(arr("int8_t", "CNN_W3", q3)); f.write(arr("int32_t", "CNN_B3", b3q))
np.save(os.path.join(HERE, "cnn_expected_pred.npy"), pq)
print("wrote cnn_tables.h and cnn_expected_pred.npy [%.0fs]" % (time.time() - t0))
